using TechMundo.Models;
using Microsoft.EntityFrameworkCore;

namespace TechMundo.Data;

public class TechMundoDbContext : DbContext
{
    public TechMundoDbContext(DbContextOptions<TechMundoDbContext> options) : base(options) { }

    public DbSet<Producto> Productos => Set<Producto>();
    public DbSet<Categoria> Categorias => Set<Categoria>();
    public DbSet<Venta> Ventas => Set<Venta>();
    public DbSet<VentaItem> VentaItems => Set<VentaItem>();

    protected override void OnModelCreating(ModelBuilder mb)
    {
        mb.Entity<Producto>(e =>
        {
            e.HasIndex(p => p.Nombre);
            e.Property(p => p.Precio).HasColumnType("decimal(18,2)");

            e.HasOne(p => p.Categoria)
             .WithMany(c => c.Productos)
             .HasForeignKey(p => p.CategoriaId)
             .OnDelete(DeleteBehavior.Restrict);
        });

        mb.Entity<Venta>(e =>
        {
            e.HasIndex(v => v.Fecha);
            e.Property(v => v.Total).HasColumnType("decimal(18,2)");
            e.HasMany(v => v.Items).WithOne(i => i.Venta).HasForeignKey(i => i.VentaId).OnDelete(DeleteBehavior.Cascade);
        });

        mb.Entity<VentaItem>(e =>
        {
            e.Property(i => i.PrecioUnitario).HasColumnType("decimal(18,2)");
            // Si se elimina un producto, el historial conserva el ítem (con su nombre y precio de ese momento).
            e.HasOne<Producto>().WithMany().HasForeignKey(i => i.ProductoId).OnDelete(DeleteBehavior.SetNull);
        });

        // Data seeding (Unidad 3, Clase 16)
